package tvxterm

import (
	"io"
	"strings"
	"testing"
)

// rowString renders a cell row as text with trailing blanks removed.
func rowString(row []Cell) string {
	return strings.TrimRight(cellsToString(row), " ")
}

// pipeBackend records writes on behalf of tests that drive the view through
// Feed. Read returns io.EOF so a read loop started by Attach exits instead of
// spinning: the tests do not feed output through the backend at all.
type pipeBackend struct {
	writes [][]byte
}

func (b *pipeBackend) Read(p []byte) (int, error) { return 0, io.EOF }

func (b *pipeBackend) Write(p []byte) (int, error) {
	b.writes = append(b.writes, append([]byte(nil), p...))
	return len(p), nil
}

func (b *pipeBackend) Resize(cols, rows int) error { return nil }

func (b *pipeBackend) Close() error { return nil }

// TestViewFeedDeliversOutputSynchronously: Feed must apply output to the
// emulator before it returns, so a caller that just fed text can read the
// resulting screen state without polling. A read loop would only deliver the
// chunk on a later Read, which is why Feed cannot be implemented as a
// channel send to readLoop.
func TestViewFeedDeliversOutputSynchronously(t *testing.T) {
	v := New(nil)
	backend := &pipeBackend{}
	v.Attach(backend)

	if !v.Feed([]byte("1111\n2222\n3333\n4444")) {
		t.Fatalf("expected Feed to report success with an attached backend")
	}

	ss := v.emu.Snapshot()
	if got := strings.TrimRight(cellsToString(ss.Cells[3]), " "); got != "4444" {
		t.Fatalf("row 3 after Feed = %q, want %q", got, "4444")
	}
}

// TestViewFeedRejectsWithoutBackend: with no backend attached there is nowhere
// to deliver output, so Feed must report failure instead of silently dropping
// the bytes.
func TestViewFeedRejectsWithoutBackend(t *testing.T) {
	v := New(nil)
	if v.Feed([]byte("hello")) {
		t.Fatal("expected Feed to fail when no backend is attached")
	}
}

// TestViewFeedDrainsTerminalResponses: terminal responses generated by fed
// output (DSR/DA replies) must be written to the backend, exactly as the read
// loop does, or the remote waits for an answer that never comes.
func TestViewFeedDrainsTerminalResponses(t *testing.T) {
	v := New(nil)
	backend := &pipeBackend{}
	v.Attach(backend)

	// DSR 6 (cursor position report) asks for a reply.
	if !v.Feed([]byte("\x1b[6n")) {
		t.Fatalf("expected Feed to report success")
	}
	if len(backend.writes) == 0 {
		t.Fatal("expected a cursor position report to be written to the backend")
	}
}
